#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/sys/mem_blocks.h>

#define BLK_SIZE	32
#define BLK_NUM		4
#define BLK_ALIGN	sizeof(void *)

#define THREAD_STACK_SIZE	(512 + CONFIG_TEST_EXTRA_STACK_SIZE)
#define THREAD_PRIORITY		5

/* +1 is added to the number of blocks to test the case where the number of
 * blocks is not a multiple of the number of bits in a bitmap word.
 */
K_MEM_BLOCK_DEFINE(test_mem_block, BLK_SIZE, BLK_NUM + 1, BLK_ALIGN);
static struct k_mem_block_stats stats;

K_THREAD_STACK_DEFINE(thread_stack_1, THREAD_STACK_SIZE);
K_THREAD_STACK_DEFINE(thread_stack_2, THREAD_STACK_SIZE);

static struct k_thread thread_1;
static struct k_thread thread_2;

static K_SEM_DEFINE(sem, 0, 2);

static void test_mem_blocks_compile_time_stats(void)
{
	/* Get the compile-time stats of the memory block */
	k_mem_block_stats_get(&test_mem_block, &stats);

	/* Check that the total number of blocks is correct */
	zassert_equal(stats.total_blocks, BLK_NUM + 1,
		      "total_blocks should be %d", BLK_NUM + 1);

	/* Check that the number of free blocks is correct */
	zassert_equal(stats.free_blocks, BLK_NUM + 1,
		      "free_blocks should be %d", BLK_NUM + 1);

	/* Check that the number of allocated blocks is correct */
	zassert_equal(stats.alloc_blocks, 0, "alloc_blocks should be 0");
}

static void test_mem_blocks_runtime_stats(void)
{
	void *blocks[BLK_NUM + 1];
	int i, status;

	/* Get the initial stats of the memory block */
	k_mem_block_stats_get(&test_mem_block, &stats);

	/* Check that the total number of blocks is correct */
	zassert_equal(stats.total_blocks, BLK_NUM + 1,
		      "total_blocks should be %d", BLK_NUM + 1);

	/* Check that the number of free blocks is correct */
	zassert_equal(stats.free_blocks, BLK_NUM + 1,
		      "free_blocks should be %d", BLK_NUM + 1);

	/* Check that the number of allocated blocks is correct */
	zassert_equal(stats.alloc_blocks, 0, "alloc_blocks should be 0");

	/* Allocate all blocks */
	for (i = 0; i < BLK_NUM + 1; i++) {
		status = k_mem_block_alloc(&test_mem_block, &blocks[i],
					   K_NO_WAIT);
		zassert_equal(status, 0, "Failed to allocate block %d", i);

		/* Get the stats of the memory block */
		k_mem_block_stats_get(&test_mem_block, &stats);

		/* Check that the total number of blocks is correct */
		zassert_equal(stats.total_blocks, BLK_NUM + 1,
			      "total_blocks should be %d", BLK_NUM + 1);

		/* Check that the number of free blocks is correct */
		zassert_equal(stats.free_blocks, BLK_NUM + 1 - (i + 1),
			      "free_blocks should be %d", BLK_NUM + 1 - (i + 1));

		/* Check that the number of allocated blocks is correct */
		zassert_equal(stats.alloc_blocks, i + 1,
			      "alloc_blocks should be %d", i + 1);
	}

	/* Try to allocate one more block */
	status = k_mem_block_alloc(&test_mem_block, &blocks[0], K_NO_WAIT);
	zassert_not_equal(status, 0, "Allocated an extra block");

	/* Free all blocks */
	for (i = 0; i < BLK_NUM + 1; i++) {
		k_mem_block_free(&test_mem_block, blocks[i]);

		/* Get the stats of the memory block */
		k_mem_block_stats_get(&test_mem_block, &stats);

		/* Check that the total number of blocks is correct */
		zassert_equal(stats.total_blocks, BLK_NUM + 1,
			      "total_blocks should be %d", BLK_NUM + 1);

		/* Check that the number of free blocks is correct */
		zassert_equal(stats.free_blocks, i + 1,
			      "free_blocks should be %d", i + 1);

		/* Check that the number of allocated blocks is correct */
		zassert_equal(stats.alloc_blocks, BLK_NUM + 1 - (i + 1),
			      "alloc_blocks should be %d", BLK_NUM + 1 - (i + 1));
	}

	/* Get the final stats of the memory block */
	k_mem_block_stats_get(&test_mem_block, &stats);

	/* Check that the total number of blocks is correct */
	zassert_equal(stats.total_blocks, BLK_NUM + 1,
		      "total_blocks should be %d", BLK_NUM + 1);

	/* Check that the number of free blocks is correct */
	zassert_equal(stats.free_blocks, BLK_NUM + 1,
		      "free_blocks should be %d", BLK_NUM + 1);

	/* Check that the number of allocated blocks is correct */
	zassert_equal(stats.alloc_blocks, 0, "alloc_blocks should be 0");
}

static void test_mem_blocks_init_stats(void)
{
	struct k_mem_block block;
	K_MEM_BLOCK_BUFFER_DEFINE(buffer, BLK_SIZE, BLK_NUM, BLK_ALIGN);

	/* Initialize the memory block */
	k_mem_block_init(&block, buffer, BLK_SIZE, BLK_NUM);

	/* Get the stats of the memory block */
	k_mem_block_stats_get(&block, &stats);

	/* Check that the total number of blocks is correct */
	zassert_equal(stats.total_blocks, BLK_NUM,
		      "total_blocks should be %d", BLK_NUM);

	/* Check that the number of free blocks is correct */
	zassert_equal(stats.free_blocks, BLK_NUM,
		      "free_blocks should be %d", BLK_NUM);

	/* Check that the number of allocated blocks is correct */
	zassert_equal(stats.alloc_blocks, 0, "alloc_blocks should be 0");
}

static void thread_entry(void *p1, void *p2, void *p3)
{
	void *block;
	int status;

	status = k_mem_block_alloc(&test_mem_block, &block, K_NO_WAIT);
	zassert_equal(status, 0, "Failed to allocate block");

	k_sem_give(&sem);

	k_mem_block_free(&test_mem_block, block);
}

static void test_mem_blocks_thread_stats(void)
{
	/* Create two threads */
	k_thread_create(&thread_1, thread_stack_1, THREAD_STACK_SIZE,
			thread_entry, NULL, NULL, NULL, THREAD_PRIORITY, 0,
			K_NO_WAIT);
	k_thread_create(&thread_2, thread_stack_2, THREAD_STACK_SIZE,
			thread_entry, NULL, NULL, NULL, THREAD_PRIORITY, 0,
			K_NO_WAIT);

	/* Wait for the threads to allocate the blocks */
	k_sem_take(&sem, K_FOREVER);
	k_sem_take(&sem, K_FOREVER);

	/* Get the stats of the memory block */
	k_mem_block_stats_get(&test_mem_block, &stats);

	/* Check that the number of allocated blocks is correct */
	zassert_equal(stats.alloc_blocks, 2, "alloc_blocks should be 2");

	/* Wait for the threads to finish */
	k_thread_join(&thread_1, K_FOREVER);
	k_thread_join(&thread_2, K_FOREVER);

	/* Get the stats of the memory block */
	k_mem_block_stats_get(&test_mem_block, &stats);

	/* Check that the number of allocated blocks is correct */
	zassert_equal(stats.alloc_blocks, 0, "alloc_blocks should be 0");
}

void test_main(void)
{
	ztest_test_suite(lib_mem_blocks_stats_test,
			 ztest_unit_test(test_mem_blocks_compile_time_stats),
			 ztest_unit_test(test_mem_blocks_runtime_stats),
			 ztest_unit_test(test_mem_blocks_init_stats),
			 ztest_unit_test(test_mem_blocks_thread_stats));
	ztest_run_test_suite(lib_mem_blocks_stats_test);
}
